package com.company.skillplatform.user.infrastructure.entity;
import com.company.skillplatform.common.infrastructure.entity.BaseJpaEntity;import jakarta.persistence.*;
@Entity @Table(name="org_team_member",uniqueConstraints=@UniqueConstraint(name="uk_org_team_member",columnNames={"team_id","user_id"})) public class OrgTeamMemberEntity extends BaseJpaEntity{@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="team_id",nullable=false)private OrgTeamEntity team;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id",nullable=false)private IamUserEntity user;@Column(name="membership_type",nullable=false,length=32)private String membershipType;protected OrgTeamMemberEntity(){}public OrgTeamMemberEntity(OrgTeamEntity t,IamUserEntity u){team=t;user=u;membershipType="MEMBER";}public OrgTeamEntity getTeam(){return team;}public IamUserEntity getUser(){return user;}public String getMembershipType(){return membershipType;}}
